clonePackage := func(pkg *runtanzuv1alpha1.TanzuClusterBootstrapPackage) error {
	if pkg == nil || pkg.ValuesFrom == nil {
		return nil
	}
	secret, err := updateValuesFromSecret(pkg.ValuesFrom, packageShortName(pkg.RefName))
	if err != nil {
		return err
	}
	createdSecrets = append(createdSecrets, secret)

	provider, err := updateValuesFromProvider(pkg.ValuesFrom, packageShortName(pkg.RefName))
	if err != nil {
		return err
	}
	createdProviders = append(createdProviders, provider)

	return nil
}

if err := clonePackage(bootstrap.Spec.CNI); err != nil {
	return nil, nil, err
}
